1	// Acceptance tests for the change request:
2	//   "Show me how much is still left to pay on each invoice after any payments."
3	//
4	// An invoice now surfaces how much is STILL LEFT to pay on it once what has been paid is taken off:
5	// invoice-due-amount = the invoice's amount MINUS the sum of every payment recorded against it. It
6	// lives on the invoice's own detail page (invoice-detail-page, reached at /invoices/<id> — the same
7	// public URL surface the invoice specs already use), the one place that shows that invoice's
8	// payments (invoice-payments). Because it is derived "after any payments", it is scoped to the ONE
9	// invoice: each invoice's due amount is worked out from its OWN payments, never a sibling's.
10	//
11	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed, which honours
12	// invoices: { id, projectId, amount, status } and payments: { id, invoiceId, amount, date }
13	// (alongside clients / projects). This change introduces NO new audit record, so nothing is asserted
14	// through the audit channel here.
15	//
16	// invoice-due-amount is MONEY but a NEW anchor, not one of the three money-format anchors the
17	// money-format spec pins exactly; so — like the sibling payment-amount anchor — it is matched
18	// leniently (a leading "$" and a trailing ".00" both optional). What this change pins is the VALUE
19	// left to pay, not its exact presentation. Amounts and the resulting remainders are chosen so no
20	// value is a substring of another, of a payment, of a date number, or of the full invoice amount:
21	// a buggy implementation that showed the full amount, or the total paid, instead of the remainder
22	// would therefore fail. This test SHOULD FAIL before the change: there is no invoice-due-amount today.
23	import { test, expect } from '@playwright/test';
24	import { resetAndSeed } from '../support/seed';
25	
26	test.describe('how much is left to pay on an invoice after payments', () => {
27	  test('shows the amount still left after subtracting the payments recorded on that invoice', async ({ page }) => {
28	    await resetAndSeed({
29	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
30	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
31	      invoices: [
32	        // 500 billed; 200 + 120 = 320 paid => 180 still left to pay.
33	        { id: 1, projectId: 1, amount: 500, status: 'SENT' },
34	        // A second invoice with its OWN payment, so invoice 1's remainder is worked out from
35	        // invoice 1's payments only, never invoice 2's.
36	        { id: 2, projectId: 1, amount: 900, status: 'SENT' },
37	      ],
38	      payments: [
39	        { id: 1, invoiceId: 1, amount: 200, date: '2025-06-15' },
40	        { id: 2, invoiceId: 1, amount: 120, date: '2025-08-20' },
41	        // Belongs to invoice 2 — must NOT reduce invoice 1's due amount.
42	        { id: 3, invoiceId: 2, amount: 777, date: '2025-01-09' },
43	      ],
44	    });
45	
46	    await page.goto('/invoices/1');
47	    await expect(page.getByTestId('invoice-detail-page')).toBeVisible();
48	
49	    // 500 - (200 + 120) = 180 still left to pay. Not the full 500, not the 320 paid.
50	    const due = page.getByTestId('invoice-due-amount');
51	    await expect(due).toBeVisible();
52	    await expect(due).toHaveText(/^\$?180(\.00)?$/);
53	
54	    // Invoice 2's remainder is 900 - 777 = 123, derived from its own payment alone — proving the
55	    // figure is per-invoice and did not leak invoice 1's payments onto it.
56	    await page.goto('/invoices/2');
57	    await expect(page.getByTestId('invoice-detail-page')).toBeVisible();
58	    await expect(page.getByTestId('invoice-due-amount')).toHaveText(/^\$?123(\.00)?$/);
59	  });
60	
61	  test('with no payments yet, the whole amount is still left to pay', async ({ page }) => {
62	    await resetAndSeed({
63	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
64	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
65	      invoices: [{ id: 1, projectId: 1, amount: 250, status: 'SENT' }],
66	      payments: [],
67	    });
68	
69	    await page.goto('/invoices/1');
70	    await expect(page.getByTestId('invoice-detail-page')).toBeVisible();
71	
72	    // Nothing paid => the full amount is still owed.
73	    await expect(page.getByTestId('invoice-due-amount')).toHaveText(/^\$?250(\.00)?$/);
74	  });
75	
76	  test('once the payments cover the amount, nothing is left to pay', async ({ page }) => {
77	    await resetAndSeed({
78	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
79	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
80	      invoices: [{ id: 1, projectId: 1, amount: 400, status: 'SENT' }],
81	      payments: [
82	        // 150 + 250 = 400 => the invoice is fully covered, so 0 is left to pay.
83	        { id: 1, invoiceId: 1, amount: 150, date: '2025-03-11' },
84	        { id: 2, invoiceId: 1, amount: 250, date: '2025-04-22' },
85	      ],
86	    });
87	
88	    await page.goto('/invoices/1');
89	    await expect(page.getByTestId('invoice-detail-page')).toBeVisible();
90	
91	    // Fully paid off => nothing still left to pay.
92	    await expect(page.getByTestId('invoice-due-amount')).toHaveText(/^\$?0(\.00)?$/);
93	  });
94	});
